    "titulua": null,
    "blokeak": [
     {
      "mota": "testua",
      "html": "<math display=\"block\"><mrow><mi>A</mi><mo>=</mo><mfrac><mn>71</mn><mn>3</mn></mfrac><mo>≈</mo><mn>23.67</mn><mspace width=\"1.0em\"></mspace><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mrow><mtext mathvariant=\"normal\">koadernoan </mtext><mspace width=\"0.333em\"></mspace></mrow><mn>22</mn><mo>,</mo><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> ik. Zuzenketa</mtext></mrow><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow></mrow></math>"
     }
    ]
