  "izar": 0,
  "blokeak": [
   {
    "mota": "testua",
    "html": "Halle la solución general de <math display=\"block\"><mrow><mover><mi>x</mi><mo accent=\"true\">̇</mo></mover><mo>=</mo><mi>x</mi><mo>−</mo><mi>y</mi><mo>,</mo></mrow></math> <math display=\"block\"><mrow><mover><mi>y</mi><mo accent=\"true\">̇</mo></mover><mo>=</mo><mi>x</mi><mo>+</mo><mn>3</mn><mi>y</mi><mi>.</mi></mrow></math>"
   }
  ],
